viewof yfCancer = Inputs.range([0.02, 0.3], {value: 0.15, step: 0.01, label: "Lung cancer, smokers"})
















yf = {
  const ps = 0.3, py0 = 0.05, pc0 = 0.01;           // non-smokers: few stains, low risk
  const pYes = ps * yfStain + (1 - ps) * py0;
  const cYes = (ps * yfStain * yfCancer + (1 - ps) * py0 * pc0) / pYes;
  const cNo  = (ps * (1 - yfStain) * yfCancer + (1 - ps) * (1 - py0) * pc0) / (1 - pYes);
  const overall = ps * yfCancer + (1 - ps) * pc0;
  return {cYes, cNo, rr: cYes / cNo, overall};
}
