mdpSpec = FileAttachment("data/precomputed/ch14/insulin_mdp.json").json()







mdp = {
  const M = mdpSpec.moves, gamma = mdpSpec.gamma, S = 20, A = 3;
  const sid = (g, r) =&gt; r * 5 + g, band = s =&gt; s % 5, rate = s =&gt; Math.floor(s / 5);
  const bandLab = ["&lt; 4", "4–6", "6–10", "10–14", "&gt; 14"], rateLab = mdpSpec.rates;
  function next(s, a, rew) {                 // a: 0 decrease, 1 keep, 2 increase
    const r2 = Math.min(3, Math.max(0, rate(s) + a - 1)), g = band(s), out = [];
    for (let m = 0; m &lt; 3; m++) { const g2 = Math.min(4, Math.max(0, g + m - 1)); out.push([M[r2][m], sid(g2, r2), rew[g2]]); }
    return out;
  }
  function solve(rew) {
    let V = new Array(S).fill(0), Q = null;
    for (let k = 0; k &lt; 3000; k++) {
      Q = d3.range(S).map(s =&gt; d3.range(A).map(a =&gt; d3.sum(next(s, a, rew), ([p, s2, r]) =&gt; p * (r + gamma * V[s2]))));
      const V2 = Q.map(q =&gt; Math.max(...q)), diff = d3.max(V2, (v, i) =&gt; Math.abs(v - V[i]));
      V = V2; if (diff &lt; 1e-10) break;
    }
    const policy = Q.map(q =&gt; q.indexOf(Math.max(...q)));
    return {V, Q, policy};
  }
  function evaluate(policy) {                // exact 24-hour occupancy from glucose 10-14, infusion off
    let d = new Array(S).fill(0); d[sid(3, 0)] = 1; const acc = {inRange: 0, hypo: 0, hyper: 0};
    for (let t = 0; t &lt; 12; t++) {
      const d2 = new Array(S).fill(0);
      for (let s = 0; s &lt; S; s++) if (d[s] &gt; 0) for (const [p, s2] of next(s, policy[s], [0, 0, 0, 0, 0])) d2[s2] += d[s] * p;
      d = d2;
      for (let s = 0; s &lt; S; s++) { const g = band(s); if (g === 2) acc.inRange += d[s] / 12; if (g === 0) acc.hypo += d[s] / 12; if (g &gt;= 3) acc.hyper += d[s] / 12; }
    }
    return acc;
  }
  const arrows = ["←", "•", "→"];
  // At 'off' a decrease changes nothing, and at 'high' neither does an increase: show them as 'keep'.
  const eff = (s, a) =&gt; (rate(s) === 0 && a === 0) || (rate(s) === 3 && a === 2) ? 1 : a;
  // Draw the 5 x 4 grid of states. cellFn(s) -&gt; {fill, label, corner, current, faded}
  function grid(cellFn, aria) {
    const cw = 104, ch = 58, x0 = 92, y0 = 44, W = x0 + 4 * cw + 12, H = y0 + 5 * ch + 34;
    const svg = d3.create("svg").attr("viewBox", `0 0 ${W} ${H}`).attr("class", "aihs-svg")
      .attr("role", "img").attr("aria-label", aria).style("max-width", "560px");
    rateLab.forEach((r, j) =&gt; svg.append("text").attr("x", x0 + j * cw + cw / 2).attr("y", y0 - 10).attr("text-anchor", "middle").attr("font-size", 13).text(r));
    svg.append("text").attr("x", x0 + 2 * cw).attr("y", 14).attr("text-anchor", "middle").attr("font-size", 13).attr("font-weight", 700).text("Insulin infusion rate →");
    for (let g = 4; g &gt;= 0; g--) {
      const row = 4 - g;
      svg.append("text").attr("x", x0 - 8).attr("y", y0 + row * ch + ch / 2 + 4).attr("text-anchor", "end").attr("font-size", 13)
        .attr("font-weight", g === 2 ? 700 : 400).text(bandLab[g] + (g === 2 ? " ★" : ""));
      for (let r = 0; r &lt; 4; r++) {
        const s = sid(g, r), c = cellFn(s), x = x0 + r * cw, y = y0 + row * ch;
        svg.append("rect").attr("x", x + 2).attr("y", y + 2).attr("width", cw - 4).attr("height", ch - 4).attr("rx", 6)
          .attr("fill", c.fill).style("stroke", c.current ? "var(--aihs-accent, #1f6f8b)" : "currentColor")
