srHits = {
  const wt = (w, c) =&gt; srW === "TF-IDF" ? c * (srIndex.idf.get(w) || 0) : c;
  const q = new Map(); srTok(srQ).forEach(w =&gt; q.set(w, (q.get(w) || 0) + 1));
  const qv = new Map([...q].map(([w, c]) =&gt; [w, wt(w, c)]));
  const qn = Math.sqrt([...qv.values()].reduce((s, x) =&gt; s + x * x, 0)) || 1;
  const keep = {"all documents": null, "Ward 7 discharge summaries": "ward7_discharge",
    "ONCO-1 adverse-event notes": "onco1_ae", "leaflet sentences": "leaflet"}[srS];
