    im.data[4 * k] = v; im.data[4 * k + 1] = v; im.data[4 * k + 2] = v; im.data[4 * k + 3] = 255;
  }
  ctx.putImageData(im, 0, 0);
  c.style.width = px + "px"; c.style.height = px + "px"; c.style.borderRadius = "6px";
  c.setAttribute("role", "img"); c.setAttribute("aria-label", "Decoded chest X-ray, 28 by 28 pixels");
  return c;
}
