diffAbar = {
  const T = 1000, a = [1];
  for (let t = 1; t &lt;= T; t++) { const beta = 1e-4 + (0.02 - 1e-4) * (t - 1) / (T - 1); a.push(a[t - 1] * (1 - beta)); }
  return a;
}
function gaussNoise(seed, n) {
  let s = seed &gt;&gt;&gt; 0;
  const rnd = () =&gt; { s = (s + 0x6D2B79F5) | 0; let t = Math.imul(s ^ s &gt;&gt;&gt; 15, 1 | s); t = t + Math.imul(t ^ t &gt;&gt;&gt; 7, 61 | t) ^ t; return ((t ^ t &gt;&gt;&gt; 14) &gt;&gt;&gt; 0) / 4294967296; };
  const out = new Float64Array(n);
  for (let i = 0; i &lt; n; i++) { let u = 0; while (u === 0) u = rnd(); out[i] = Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * rnd()); }
  return out;
}
function signedImg(vals, px) {
  const c = document.createElement("canvas"); c.width = 28; c.height = 28;
  const ctx = c.getContext("2d"), im = ctx.createImageData(28, 28);
  for (let k = 0; k &lt; 784; k++) {
    const v = Math.max(0, Math.min(255, Math.round((vals[k] + 1) * 127.5)));
    im.data[4 * k] = v; im.data[4 * k + 1] = v; im.data[4 * k + 2] = v; im.data[4 * k + 3] = 255;
  }
  ctx.putImageData(im, 0, 0);
  c.style.width = px + "px"; c.style.height = px + "px"; c.style.borderRadius = "6px";
  c.setAttribute("role", "img"); c.setAttribute("aria-label", "Chest X-ray with added noise");
  return c;
}
function pearson(a, b) {
  const ma = d3.mean(a), mb = d3.mean(b);
  let sab = 0, saa = 0, sbb = 0;
  for (let i = 0; i &lt; a.length; i++) { const da = a[i] - ma, db = b[i] - mb; sab += da * db; saa += da * da; sbb += db * db; }
  return sab / Math.sqrt(saa * sbb);
}
